    assert.deepEqual(calls, []);
  }

  for (const value of [null, {}, 1]) {
    const calls = [];
    const cursor = {
      take() {
        calls.push("take");
        return Promise.resolve({ rows: [], end: true });
      },
      abort() {
        calls.push("abort");
      },
      close() {
        calls.push("close");
      },
    };

    await assert.rejects(
      consumeBatches({
        cursor,
        sink: value,
        signal: signalController().signal,
      }),
      TypeError,
